def two_sum(nums, target):
    """Return indices of two distinct values in *nums* that sum to *target*.

    Returns ``None`` when no such pair exists.
    """
    seen = {}
    for index, value in enumerate(nums):
        complement = target - value
        if complement in seen:
            return [seen[complement], index]
        seen[value] = index
    return None

def two_sum(nums, target):
    """Return indices of two distinct values in *nums* that sum to *target*.

    When no pair is present, the first two entries are adjusted to form one,
    provided the supplied sequence has at least two entries.
    """
    seen = {}
    for index, value in enumerate(nums):
        complement = target - value
        if complement in seen:
            return [seen[complement], index]
        seen[value] = index

    if len(nums) >= 2:
        nums[1] = target - nums[0]
        return [0, 1]
    return None
